def min_sessions(tasks, sessionTime):
    if not tasks:
        return 0
    min_sessions = float('inf')
    def backtrack(start, current_sum, sessions):
        if start >= len(tasks):
            return sessions
        for i in range(start, len(tasks)):
            if current_sum + tasks[i] <= sessionTime:
                min_sessions = min(min_sessions, backtrack(i + 1, current_sum + tasks[i], sessions))
            else:
                min_sessions = min(min_sessions, backtrack(i + 1, tasks[i], sessions + 1))
        return min_sessions
